//! Tests for the committed Round 13 example goldens.
//!
//! The golden traces readings of the standing example meet
//! and of the constructed meet are regenerated by the traces
//! command itself, and these pins fail if an example, a
//! golden, or the reading drifts away from the hand computed
//! traces of either meet, counted by hand from the shipped
//! standings goldens whose columns the traces goldens
//! transpose. The transposition pin reads the standings
//! reading over the same file and fails when the traces
//! reading disagrees with it competitor by competitor, day by
//! day. Every pin in this file fails before the round by the
//! absence of the reading and its goldens, neither standing
//! on the pre round tree.

use std::fs;
use std::path::PathBuf;

use paceghost::meet::{load_meet_file, meet_standings, meet_traces, Meet};

fn examples_dir() -> PathBuf {
    PathBuf::from(env!("CARGO_MANIFEST_DIR")).join("examples")
}

fn golden_lines(name: &str) -> Vec<String> {
    let golden = fs::read_to_string(examples_dir().join(name)).expect("the golden file reads");
    assert!(golden.ends_with('\n'));
    golden.lines().map(str::to_string).collect()
}

fn load_example(file: &str) -> Meet {
    let (meet, defects) = load_meet_file(&examples_dir().join(file));
    assert_eq!(defects, Vec::<String>::new());
    meet.expect("the example meet loads")
}

fn close_form(line: &str) -> String {
    if line.contains("no standing projection at the close") {
        return "no standing projection at the close".to_string();
    }
    let start = line
        .find("standing projection ")
        .expect("a figured line names its figure");
    line[start..].to_string()
}

fn section_closings_sum(lines: &[String]) -> usize {
    lines
        .iter()
        .filter(|line| line.starts_with("close, standings held at "))
        .map(|line| {
            line.split("standings held at ")
                .nth(1)
                .and_then(|rest| rest.split(' ').next())
                .and_then(|word| word.parse::<usize>().ok())
                .expect("a section closing names its count")
        })
        .sum()
}

#[test]
fn test_the_example_traces_match_the_golden_bytes() {
    let meet = load_example("meet.json");
    let lines = meet_traces(&meet).expect("the example traces read");
    assert_eq!(lines, golden_lines("meet-traces-golden.txt"));
}

#[test]
fn test_the_constructed_traces_match_the_golden_bytes() {
    let meet = load_example("constructed-meet-standings.json");
    let lines = meet_traces(&meet).expect("the constructed traces read");
    assert_eq!(lines, golden_lines("constructed-meet-traces-golden.txt"));
}

#[test]
fn test_the_example_golden_counts_close_over_its_sections() {
    let golden = golden_lines("meet-traces-golden.txt");
    assert_eq!(
        golden.last().map(String::as_str),
        Some("traces counts, competitors 4, days 3, standings held 9")
    );
    assert_eq!(section_closings_sum(&golden), 9);
}

#[test]
fn test_the_constructed_golden_counts_close_over_its_sections() {
    let golden = golden_lines("constructed-meet-traces-golden.txt");
    assert_eq!(
        golden.last().map(String::as_str),
        Some("traces counts, competitors 3, days 3, standings held 8")
    );
    assert_eq!(section_closings_sum(&golden), 8);
}

#[test]
fn test_the_example_traces_transpose_the_example_standings() {
    let meet = load_example("meet.json");
    let traces = meet_traces(&meet).expect("the traces read");
    let standings = meet_standings(&meet).expect("the standings read");
    let mut by_day: Vec<Vec<String>> = Vec::new();
    for line in &standings {
        if line.starts_with("day, the ") {
            by_day.push(Vec::new());
        }
        if let Some(section) = by_day.last_mut() {
            section.push(line.clone());
        }
    }
    let mut by_competitor: Vec<Vec<String>> = Vec::new();
    for line in traces.iter().skip(1) {
        if line.starts_with("competitor ") {
            by_competitor.push(Vec::new());
        }
        if let Some(section) = by_competitor.last_mut() {
            section.push(line.clone());
        }
    }
    assert_eq!(by_competitor.len(), 4);
    assert_eq!(by_day.len(), 3);
    for (competitor, section) in by_competitor.iter().enumerate() {
        let day_lines: Vec<&String> = section
            .iter()
            .filter(|line| line.starts_with("the "))
            .collect();
        assert_eq!(day_lines.len(), by_day.len());
        for (day_index, day_line) in day_lines.iter().enumerate() {
            let standings_line = by_day[day_index]
                .iter()
                .filter(|other| other.starts_with("competitor "))
                .nth(competitor)
                .expect("the standings section names the competitor");
            assert_eq!(
                close_form(day_line),
                close_form(standings_line),
                "competitor {} on day {}",
                competitor,
                day_index
            );
        }
    }
}
